    subtitle: 'OT 安全公司 Frenos 首份年度报告：6 个美国前沿模型、2 个美国开源与 2 个外国开源模型同场接受工业设施攻击规划测试；前三个前沿模型以 100% 覆盖率、约 90% 一致性领先，但其余三个前沿模型骤降至 18%-32%；最强外国开源模型以 77% 覆盖率、36% 一致性反超三个美国前沿模型，最强美国开源模型仅 5%。报告同时强调：测试在简单模拟器中进行，不能证明模型能自主找到目标并实施 OT 攻击',
