      '时间线由组织方与 Meta 双方拼出：10 月 17 日下午 1 点（美东时间）前后，No Kings 联盟的 Instagram 主页被自动系统拿下；约一小时后，自动复核认定"本不该封禁"并恢复页面展示，但组织者仍无法登录管理账号；全部管理权限直到下午 5 点 33 分才恢复。对一场依赖 Instagram 联络支持者、发布活动信息的全国性动员来说，被封的恰好是最关键的那几个小时——该组织称当天 50 个州及华盛顿特区共举行近 3000 场活动、数百万人参与，诉求是扩大提前投票渠道与维护选举公正性。',
      'Meta 的解释本身经历了一次悄悄换挡。事发当天，公司将封禁归因于该账号"异常频繁的发帖、转发与评论"，称行动"显然是错误"；次日（10 月 18 日），Stone 在社交平台公布了完全不同的版本：Instagram 工程团队查明，触发错误执法的峰值主要来自账号的"读取"行为——网络安全系统检测到一款 Claude 工具在 10 月 17 日以约 4 倍于正常的量、以密集突发方式读取该账号的主页、帖子与话题标签。"短时间内这类突发、大量且连续的访问请求，特征更像自动化机器人流量而非普通用户浏览平台。"Stone 写道，并再次致歉。两个版本从未被调和：Indivisible 联合创始人 Leah Greenberg 公开表示"这个借口与事实不符"。',
      '关键信息至今仍缺失：Meta 没有说明涉及 Claude 的哪款工具、由谁操作、为何密集访问这个特定账号，也无法说明该访问是否获得账号运营者授权。换言之，一个身份不明的第三方智能体读取了一个政治组织的公开页面，其后果——账号被封——却由被读取的组织承担。政治反应随之而来：参议员 Chris Murphy 称封禁"骇人"，参议员 Chris Van Hollen 质问 Meta 是否在"以审查言论自由来讨好"特朗普总统。',
      '同一天披露的行业数据解释了为什么这类误伤会越来越多。思科告诉 Rest of World：在其测试中，智能体完成单个任务产生的流量可达人类的 450%；Cloudflare 网络上来自 AI 智能体的日请求量一年增长超过 1700%。嘉信理财（Charles Schwab）CEO 则对《华尔街日报》表示，他对让 AI 智能体自主交易股票持怀疑态度。整个行业用两年时间建造了替人阅读网络的智能体，而网络现有的防御体系分不出这种流量与攻击的区别——No Kings 账号是第一起误伤在关键日子击中关键目标的案例。',
