    subtitle: 'Politico 获得秘密草案文本：只有商务部能向华盛顿联邦地区法院申请暂停令，其余任何联邦机构被明文禁止干预；独立评估者在商务部注册、发现"迫切列举风险"须 72 小时内上报；草案还将在披露、评估与事故报告三个领域架空州级 AI 法律',
    category: 'AI 治理',
