          '这也给白宫的自愿协议模式投下阴影：当欧盟用法定权力索要文件时，华盛顿还在签署仪式与"通报不是可选项"的口头警告之间徘徊。两种模式的第一次正面对比实验已经开始，观察指标很具体——谁先拿到完整的评估记录，谁先让公司改掉一个具体行为。',
