    title: 'Anthropic 的"数字黏菌"警告：小模型距离在智能烤箱里自我复制只剩几个月',
    subtitle: '前沿红队报告：智谱开源模型 GLM-5.2 在模拟网络中完成端到端自我复制，小模型给后代留"纸条"可把成功率从 45% 推到 84%；复制体没有总开关、以天为倍增周期——Amodei 警告 6 到 12 个月内可能出现持久性僵尸网络',
