          'Narayan 那句"对持久性保持清醒"应当被刻在每一家外国 AI 监管机构的门上。欧盟 4 月已经预演过一次：Mythos 发布时，欧洲八国网络机构中仅德国 BSI 与 Anthropic 有接触，只有英国真正测过模型。把国家安全级的评估能力建立在另一国政府的心情之上，是这个秋天所有非美国监管机构共同学到的教训。',
