          '值得观察的是英国选择的载体：不是单独立一部 AI 法，而是把 AI 义务嵌入既有网络安全立法。这比美国的单独立法路径阻力小得多，也给了"AI 安全"一个现成的执法机构（NCSC）与既有罚则。如果走通，这会成为中小法域的模板——不必等待完美的 AI 法，先让 AI 事故在网安法里变得必须报告。',
