    subtitle: 'Korbak、Balesni、Wang 致信 OpenAI 董事会与安全委员会并公开离职细节：口头告知、无书面理由、暗示泄露知识产权；公司罕见公开回应解雇"与安全发声无关"，并称同意信中建议——第三方评估承诺遭遇信任危机',
    category: 'AI 安全',
