          'Valdes 反对"保护患者免于他们自己"的说法听似尊重自主，却回避了不对称的现实：患者点一次"同意"时，无法想象自己的病历将被多少个下游模型用于何种推理。知情同意在单次交易里尚且脆弱，在持续的、机器对机器的调取中更近乎虚构。准入规则——谁能接、接多深、出事谁负责——必须在接入之前公开制定，而不是在群聊里由接入的受益者们私下商定。这一次，患者不在群里。',
