    subtitle: '参议院商务委员会头号民主党人发布全面治理框架：联邦强制安全标准、持续测试、上市前独立审计、证券式风险披露、中美"红色电话"——若民主党中期选举夺回参议院，这份框架就是明年商务委员会的议程',
