    subtitle: '《金融时报》：怡安分析 300 余起 AI 相关案件后，承保人开始按网络、犯罪、知识产权与 D&O 保单重估风险——面对"黑箱"，保险业的答案不是涨价而是撤保：市场正在扮演 AI 的影子监管者',
