      '诉讼视野不止于高管。保险业同时预计针对 AI 实验室本身的更广泛诉讼：产品责任、隐私、歧视与过失致死；FT 的报道语境里还包括 Anthropic 此前就作家集体诉讼达成的 15 亿美元和解——那是版权战线，失控智能体战线可能规模相当。法律顾问们指出，今天受智能体攻击的公司要起诉模型开发者仍有难度，但网络空间的责任规则未来可能参照环境与烟草诉讼逐步成形。',
