          '这对治理辩论是个冷峻的提醒：监管不必等待华盛顿。保险、审计、诉讼这三条市场通道一旦咬合，会形成一个"没有立法的监管体系"——它的缺点是覆盖不均（只有买得起保险、上得了市的公司被约束），优点是它已经在运转。',
