          '如果市议会在纽约州最高法院胜诉，先例效应将超过纽约本身：在联邦层面立法停滞的真空里，美国有数百个拥有传票权的州与地方立法机构。"影子监管"的版图可能由此打开——这不是最好的治理方式，但在华盛顿选择自愿框架的当下，它是唯一正在运转的问责机制。',
