          '但完整的账本还有另一面：同期 Anthropic 营收与估值创新高、IPO 在即，拒绝军方并未摧毁它的商业前景。这对行业是重要的反例——"安全必然输给商业"的宿命论被打破了一角。五角大楼可以惩罚一家公司，却无法惩罚它的原则所代表的市场需求。',
