          '但有一个分歧是真实且值得盯住的：对"集中"的容忍度。Altman 把能力集中于单一实验室视为比失控风险更不可接受的选项，这等于把"防止垄断"排在了"防止失控"之前。在监管设计中，这两个目标的排序决定了完全不同的制度——前者指向开放扩散与反垄断，后者指向许可制与能力阈值。华盛顿接下来数月将被迫在这两种世界观之间做选择，而不再是含糊地两头安抚。',
