          '这不是 OpenAI 一家的困境，而是行业性的制度空白：安全研究天然具有公共品属性（它的价值在于被广泛知晓与验证），却寄生于对保密有天然需求的商业组织。如果不存在受法律保护的披露通道——比如加州 SB 53 为前沿实验室员工提供的吹哨人保护——那么"内部控制"四个字就永远依赖公司自愿放行。',
