          '这也给了 FTC 调查一个新的观察角度：其调查核心是"行业的安全声明是否与运营现实相符"，而对待安全研究员的方式恰恰是声明与现实之间最诚实的对照组。霍利的传票威胁、FTC 的民事调查令与这起解雇案，都指向同一个文件柜——OpenAI 内部关于失控事件知道什么、何时知道、谁试图说出来。',
