          '如果 FTC 强制 METR 高管作证，"审计方到底看到了什么"将第一次成为联邦执法记录的一部分。这会把一个技术问题变成制度问题：当审计的深度由被审计者决定时，"独立审计"四个字究竟值多少？答案将直接决定白宫协议第三层控制的含金量。',
