    title: '加州签署全国首个"机器人老板"法案：AI 不能单独解雇任何人',
    subtitle: '纽森在 9 月 30 日截止日签署 SB 947、SB 951、AB 1883 等一揽子法案：纪律与解雇必须有人类复核、AI 导致的大规模裁员须提前告知、职场情绪与神经数据监控被禁',
    category: 'AI 治理',
