          '但这副骨架的形状值得认真对待：内部控制—内部核查—外部审计—董事会委员会，这是萨班斯-奥克斯利式的财务内控结构在 AI 安全上的移植。它的意义不在于今天约束了谁，而在于确立"未来若要立法，就按这个模子刻"的先入为主——协议里那句"假以时日可以编纂为法律"，等于行业把起草笔递给了自己。Paul 参议员担心的"责任盾牌"与 Hawley 要求的"强制测试"，争的正是这副骨架将来填充什么肉。',
