          '军事危机沟通的历史经验是：通道的价值不在和平时期的使用频率，而在危机时刻"电话能打通"。AI 事件通报机制要获得同样的地位，需要至少一次真实事件的成功演练——而双方大概都不希望那次演练到来。',
