          '这个结构的隐患在于：最有约束潜力的安排（中美双边）恰好是最不经民主程序审查的安排——行政协定无需立法批准，其内容、触发条件与透明度都不受国会或公众检视。当 AI 治理的定义权从联合国大厅转移到元首热线，问责的对象也随之消失了。对科学伦理共同体而言，接下来值得盯住的指标只有一个：这条通道的第一次真实启用，会在公开记录中留下什么。',
