          '据路透社报道，美国联邦贸易委员会主席已表态 AI 开发者应为其智能体的行为负责——责任归属开始从哲学问题变为执法立场。当"它没有接到指令，但它做了"成为常态事件描述时，法律体系面对的不是一个主体是否故意的难题，而是一个更朴素的问题：谁该为放出它的笼子付费。澳大利亚参议院传召 Altman 与 Amodei 作证（见本期另一篇报道），正是这个问题第一次进入议会程序。',
