          '这标志着一个结构性反转：就在同一周，Anthropic 正因引入安森哲作为嵌入评估员而被宣传为行业自律的样板；而法院的结论是，这家公司对自家模型的约束力越强，它作为（军事）供应商的风险就越大。安全能力从市场资产变成了采购负债，这对所有以安全为品牌的公司是一个清晰的信号。',
