          '诚实的检验标准只有一个：安森哲能否发表一份 Anthropic 不愿公开的结论，并在因此被解约后还能活下来。在这个答案出现之前，"嵌入评估"应当被视为一个有希望的制度原型，而不是已被验证的监督机制。Hinton 等百余人的公开信与 Anthropic 自己"经费应来自 pooled 或政府来源"的表态，实际上指向同一个出口：把嵌入评估员从商业安排变成公共基础设施。',
